(729,1556,'Fractures of the larger bone of the forearm.','en',2,'2026-10-08 22:02:03',NULL,NULL,'12461FFFFFFFFFFFFFFFFFFFFFFFFFFFFFFF'),
(730,1561,'Inflammation, acute or chronic, of the esophagus caused by bacteria, chemicals, or trauma.','en',2,'2026-10-08 22:02:03',NULL,NULL,'12422FFFFFFFFFFFFFFFFFFFFFFFFFFFFFFF'),
(731,1563,'Bleeding in the gastrointestinal tract.','en',2,'2026-10-08 22:02:03',NULL,NULL,'12344FFFFFFFFFFFFFFFFFFFFFFFFFFFFFFF'),
